// --- shared: csv ---
function parseCSV(text) {
  var rows = [], row = [], cur = '', q = false, s = String(text || '').replace(/^﻿/, '').replace(/\r\n?/g, '\n');
  for (var i = 0; i < s.length; i++) {
    var c = s[i];
